GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """Greedily place models, then improve the minimax KVPR with moves and swaps."""
    if gpu_num <= 0:
        raise ValueError("gpu_num must be positive")

    pressure = [m.req_rate / m.slo for m in models]
    order = sorted(
        range(len(models)),
        key=lambda i: (models[i].model_size, pressure[i]),
        reverse=True,
    )

    groups = [[] for _ in range(gpu_num)]
    used = [0.0] * gpu_num
    load = [0.0] * gpu_num

    def metric():
        ratios = [
            load[g] / (GPU_MEM_SIZE - used[g])
            if used[g] < GPU_MEM_SIZE else float("inf")
            for g in range(gpu_num)
        ]
        return max(ratios), sum(ratios)

    for i in order:
        candidates = [
            g for g in range(gpu_num)
            if used[g] + models[i].model_size <= GPU_MEM_SIZE
        ]
        if not candidates:
            raise ValueError(
                f"Unable to place model of size {models[i].model_size} GB"
            )
        g = min(
            candidates,
            key=lambda x: (
                (load[x] + pressure[i]) /
                (GPU_MEM_SIZE - used[x] - models[i].model_size),
                used[x] + models[i].model_size,
            ),
        )
        groups[g].append(i)
        used[g] += models[i].model_size
        load[g] += pressure[i]

    improved = True
    while improved:
        improved = False
        current = metric()

        for src in range(gpu_num):
            for i in list(groups[src]):
                for dst in range(gpu_num):
                    if src == dst or used[dst] + models[i].model_size > GPU_MEM_SIZE:
                        continue
                    groups[src].remove(i)
                    groups[dst].append(i)
                    used[src] -= models[i].model_size
                    used[dst] += models[i].model_size
                    load[src] -= pressure[i]
                    load[dst] += pressure[i]
                    candidate = metric()
                    if candidate < current:
                        current = candidate
                        improved = True
                        break
                    groups[dst].remove(i)
                    groups[src].append(i)
                    used[src] += models[i].model_size
                    used[dst] -= models[i].model_size
                    load[src] += pressure[i]
                    load[dst] -= pressure[i]
                if improved:
                    break
            if improved:
                break

    return {
        g: [models[i] for i in groups[g]]
        for g in range(gpu_num)
    }

